export type FoodLogDetailMode = 'log' | 'add-ingredient';

/**
 * Story 353 — the match a label read fills in: a scan that resolved, but to a
 * product with no nutrition. The match supplies the identity; the label, the numbers.
 */
export type LabelDraftTarget =
    | { kind: 'product'; product: OFFProduct }
    | { kind: 'library'; item: FoodItem };

/**
 * Story 353 — what a label read may write onto an existing row: the numbers and
 * the base they are per, never the row's identity. A field the read left unset
 * stays unset, so the PATCH leaves that column as it was. Story 355 adds the
 * photo taken for a row that has none.
 */
export type LabelNutritionUpdate = Pick<NewFoodItem,
    | 'source' | 'base_amount' | 'base_unit' | 'default_serving_amount' | 'serving_label' | 'image_path'
    | LabelReadField
>;

function labelNutritionUpdate(read: NewFoodItem): LabelNutritionUpdate {
    return {
        source: read.source,
        base_amount: read.base_amount,
        base_unit: read.base_unit,
        default_serving_amount: read.default_serving_amount,
        serving_label: read.serving_label,
        calories_per_base: read.calories_per_base,
        protein_g_per_base: read.protein_g_per_base,
        carbs_g_per_base: read.carbs_g_per_base,
        fat_g_per_base: read.fat_g_per_base,
        fiber_g_per_base: read.fiber_g_per_base,
        sugar_g_per_base: read.sugar_g_per_base,
        sodium_mg_per_base: read.sodium_mg_per_base,
    };
}

/**
 * Story 338 — an unread macro named the way a label names it, not the way the
 * column does. "sodium_mg_per_base" is not a thing anyone reads off a package.
 */
const UNREAD_FIELD_LABELS: Record<LabelReadField, string> = {
    calories_per_base: 'energy',
    protein_g_per_base: 'protein',
    carbs_g_per_base: 'carbohydrate',
    fat_g_per_base: 'fat',
    fiber_g_per_base: 'fibre',
    sugar_g_per_base: 'sugars',
    sodium_mg_per_base: 'salt',
};

function describeUnreadField(field: LabelReadField): string {
    return UNREAD_FIELD_LABELS[field] ?? field;
}

/** The order the label prints them in, so the note reads like the table did. */
function sortUnread(fields: LabelReadField[]): LabelReadField[] {
    return [...fields].sort((a, b) => LABEL_READ_FIELDS.indexOf(a) - LABEL_READ_FIELDS.indexOf(b));
}

function offProductToNewFoodItem(product: OFFProduct): NewFoodItem {
    // The server-side OFF image adopter (story 125) reads image_url out of
    // raw_json so it doesn't have to round-trip OFF a second time. Anything
    // else worth keeping for future RAG/debugging can ride along here.
    const rawJsonPayload: Record<string, unknown> = {};
    if (product.image_url) rawJsonPayload.image_url = product.image_url;
    const raw_json = Object.keys(rawJsonPayload).length > 0 ? JSON.stringify(rawJsonPayload) : undefined;

    return {
        canonical_name: product.product_name,
        display_name: product.product_name,
        brand: product.brands,
        barcode: product.barcode,
        source: 'openfoodfacts',
        source_ref: product.barcode,
        // Story 369: the server's branded fall-through maps a hit with these same two calls.
        default_serving_amount: offDefaultServing(product),
        ...offNutritionToFoodItem(product),
        raw_json,
    };
}
