/**
 * Detail emitted by `food-log-detail` when the user presses "Log Food".
 * Discriminated by `kind`:
 *   - `existing`: the food item already exists; the parent posts a consumption entry.
 *   - `new`: the food item doesn't exist yet (e.g. an OFF product the user just
 *     picked); the parent calls the combined create+log endpoint so the food
 *     row and the consumption row commit atomically — no orphan on failure.
 */
export interface FoodLogEntryExisting {
    kind: 'existing';
    food_item_id: string;
    meal_type: MealType;
    amount: number;
    /** Eaten-at wall-clock `HH:MM` from the editable time field (story 260); null when cleared. The screen anchors it on its date. */
    consumed_time: string | null;
    /**
     * Story 353 — set when a label read filled in this row: the parent writes it
     * onto the row before logging. A new row is not an option there, because
     * `food_items.barcode` is UNIQUE and `createAndLog` would reuse the empty one.
     */
    food_item_update?: LabelNutritionUpdate;
}

export interface FoodLogEntryNew {
    kind: 'new';
    new_food_item: NewFoodItem;
    meal_type: MealType;
    amount: number;
    /** Eaten-at wall-clock `HH:MM` (story 260); null when cleared. */
    consumed_time: string | null;
}

export type FoodLogEntry = FoodLogEntryExisting | FoodLogEntryNew;

export class FoodLogDetail extends HTMLElement {
    static get observedAttributes() { return ['mode']; }

    private productValue: OFFProduct | null = null;
    private libraryItemValue: FoodItem | null = null;
    /** Story 338 — a read label, held as a proposal until Log Food turns it into a row. */
    private labelDraftValue: LabelReadResult | null = null;
    /** Story 353 — the empty match that draft fills in, if it came from one. */
    private labelTargetValue: LabelDraftTarget | null = null;
    private defaultMealTypeValue: MealType | null = null;
    private modeValue: FoodLogDetailMode = 'log';
    private readonly log = createComponentLogger('food-log-detail');
    /**
     * Story 355 — a photo for a food Log Food is about to create (an OFF product
     * with no picture, a label draft). There is no row to PATCH yet, so it is
     * held here and sent on the create payload.
     */
    private newFoodImagePath: string | null = null;
    /** Story 403: `<photo-controls>` has an upload in flight. */
    private photoUploading = false;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles, bindingStyles];
        shadow.appendChild(template.content.cloneNode(true));
        // A food can be shown before this view is connected; <photo-controls> would only
        // upgrade then (story 380's reason). Upgrade it now.
        customElements.upgrade(shadow);

        const photo = shadow.getElementById('photo') as PhotoControls;
        photo.addEventListener(HEALTH_EVENTS.PHOTO_PICKED, (e) => { e.detail.respondWith = this.takePhoto(e.detail.image_path); });
        photo.addEventListener(HEALTH_EVENTS.PHOTO_REMOVED, (e) => { e.detail.respondWith = this.takePhoto(null); });
        photo.addEventListener(HEALTH_EVENTS.PHOTO_LANDED, (e) => {
            if (this.libraryItemValue) this.libraryItemValue = { ...this.libraryItemValue, image_path: e.detail.image_path };
        });
        photo.addEventListener(HEALTH_EVENTS.PHOTO_UPLOADING, (e) => {
            this.photoUploading = e.detail.uploading;
            this.renderLogHold();
        });

        // Story 372: food-log's connectedCallback runs before this element is upgraded, so what it
        // sets lands as an own property shadowing the setter. A reach-into-the-shadow-root in
        // food-log papered over it for the meal type. Re-apply both through their setters.
        const self = this as unknown as Record<string, unknown>;
        for (const name of ['mode', 'defaultMealType']) {
            if (!Object.prototype.hasOwnProperty.call(this, name)) continue;
            const value = self[name];
            delete self[name];
            self[name] = value;
        }
    }

    attributeChangedCallback(name: string, _oldValue: string | null, newValue: string | null): void {
        if (name === 'mode' && newValue) {
            this.modeValue = newValue as FoodLogDetailMode;
            this.applyMode();
        }
    }

    connectedCallback(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('back-btn')!.addEventListener('click', () => this.dispatchEvent(createFoodLogBackEvent()));

        // Story 344: the parent owns the single consent flag — this view is one of two
        // places it can be given, and the binding is written by the screen, not here.
        shadow.getElementById('bind-consent')!.addEventListener('change', (event) => {
            this.dispatchEvent(createBindConsentChangeEvent({ consent: (event.target as HTMLInputElement).checked }));
        });
        // Story 338: the "give it a name" complaint retracts the moment it is
        // answered, rather than sitting there contradicting the filled-in field.
        shadow.getElementById('draft-name')!.addEventListener('input', () => {
            shadow.getElementById('draft-name-error')!.hidden = true;
        });
        // Story 371: disabled until the log settles, so a double tap logs once.
        const logBtn = shadow.getElementById('log-btn') as HTMLButtonElement;
        logBtn.addEventListener('click', () => void whileBusy(logBtn, () => this.handleLog()));
        shadow.getElementById('archive-btn')!.addEventListener('click', () => this.handleArchiveToggle());

        this.applyMealTypeSelection();
        this.applyMode();
    }

    set defaultMealType(mealType: string | null) {
        if (!mealType || !MEAL_TYPES.includes(mealType as MealType)) {
            this.defaultMealTypeValue = null;
            this.applyMealTypeSelection();
            return;
        }
        this.defaultMealTypeValue = mealType as MealType;
        this.applyMealTypeSelection();
    }

    set mode(value: FoodLogDetailMode) {
        this.modeValue = value;
        this.applyMode();
    }

    private applyMode(): void {
        const shadow = this.shadowRoot;
        if (!shadow) return;
        const mealRow = shadow.getElementById('meal-type-row');
        const logBtn = shadow.getElementById('log-btn');
        if (mealRow) mealRow.hidden = this.modeValue === 'add-ingredient';
        if (logBtn) logBtn.textContent = this.modeValue === 'add-ingredient' ? 'Add to meal' : 'Log Food';
        // Image-action visibility depends on mode (library + log → editable;
        // add-ingredient → read-only thumb only).
        (shadow.getElementById('photo') as PhotoControls).editable = this.photoTarget().editable;
        this.renderLogHold();
        this.renderArchiveState();
    }

    private renderArchiveState(): void {
        const shadow = this.shadowRoot;
        if (!shadow) return;
        const archiveBtn = shadow.getElementById('archive-btn') as HTMLButtonElement | null;
        const flag = shadow.getElementById('archived-flag') as HTMLElement | null;
        if (!archiveBtn || !flag) return;

        // Archive lives on the food_items row; only library items in 'log'
        // mode get the action. OFF products and add-ingredient mode skip it.
        const eligible = !!this.libraryItemValue && this.modeValue === 'log';
        archiveBtn.hidden = !eligible;
        if (!eligible) {
            flag.hidden = true;
            return;
        }

        const archived = !!this.libraryItemValue!.archived_at;
        archiveBtn.textContent = archived ? 'Unarchive' : 'Archive';
        flag.hidden = !archived;
    }

    private async handleArchiveToggle(): Promise<void> {
        if (!this.libraryItemValue || this.modeValue !== 'log') return;
        const archived = !!this.libraryItemValue.archived_at;
        try {
            const updated = await HealthService.updateFoodItem(this.libraryItemValue.id, {
                archived_at: archived ? null : Temporal.Now.instant().toString(),
            });
            this.libraryItemValue = updated;
            this.renderArchiveState();
            if (!archived) {
                // The row is now archived and won't appear in the picker;
                // step back so the user lands in the prior screen.
                this.dispatchEvent(createFoodLogBackEvent());
            }
        } catch (err) {
            this.log.error('food archive toggle failed', err);
        }
    }

    showProduct(product: OFFProduct): void {
        this.productValue = product;
        this.libraryItemValue = null;
        this.clearLabelDraft();
        this.releaseNewFoodImage();
        const shadow = this.shadowRoot!;
        shadow.getElementById('product-name')!.textContent = product.product_name;
        shadow.getElementById('product-brand')!.textContent = product.brands ?? '';
        this.renderMatchNote(product);
        this.showPhoto();

        (shadow.getElementById('serving-form') as FoodServingForm).data = offProductToFormData(product);
        this.applyMealTypeSelection();
    }

    /**
     * Story 337 — an in-store barcode resolved through its item code carries the
     * nutrition of a DIFFERENT package of the same product. Saying so is the point:
     * the identity is reliable, the grams are a sibling's, and spike 336 found real
     * contributor noise inside item-code clusters ("Rosbief" vs "Rosbief Peper").
     */
    private renderMatchNote(product: OFFProduct | null): void {
        this.setMatchNote(product?.matched_by === 'item_code'
            ? `Matched by product code (${product.matched_barcode}) — this exact package wasn't found, so check the values.`
            : null);
    }

    /**
     * The library row for this OFF product: the one already carrying its barcode, or a new one.
     * Story 369: a row found only through the in-store item code is a different product as far
     * as identity goes — another retailer may use the same code.
     */
    private async offProductRow(product: OFFProduct): Promise<FoodItem> {
        const existing = product.barcode ? await HealthService.findFoodItemByBarcode(product.barcode) : null;
        if (existing && existing.matched_by !== 'item_code') return existing;
        return HealthService.createFoodItem(offProductToNewFoodItem(product));
    }

    private setMatchNote(text: string | null): void {
        const note = this.shadowRoot!.getElementById('match-note') as HTMLElement | null;
        if (!note) return;
        note.textContent = text ?? '';
        note.hidden = text === null;
    }

    /**
     * Story 342/344 — the scanned code this save can also bind, offered BEFORE the save.
     *
     * The item-code path (337) saves the row under a sibling's code, so nothing on screen
     * otherwise connects what was scanned to what is being saved. 344 made it an opt-in
     * rather than a statement: there is no pick here to mistake for consent, so the box
     * is the only thing that authorises a mapping, and it starts unticked like the
     * banner's.
     */
    setPendingBind(barcode: string | null, consent = false): void {
        const shadow = this.shadowRoot;
        const note = shadow?.getElementById('bind-note') as HTMLElement | null;
        const box = shadow?.getElementById('bind-consent') as HTMLInputElement | null;
        if (!note || !box) return;
        box.checked = Boolean(barcode) && consent;
        if (barcode) {
            shadow!.getElementById('bind-note-text')!.textContent =
                `Also remember ${barcode} — ${describeBarcodeBinding(barcode).scope}`;
            note.hidden = false;
        } else {
            shadow!.getElementById('bind-note-text')!.textContent = '';
            note.hidden = true;
        }
    }

    /**
     * Story 338 — open a read label for review. A **proposal**: nothing is
     * saved until Log Food, because the nutrition table is the part of a
     * package most likely to be misread and a photo does not get to write a row
     * unseen.
     *
     * Everything the read is unsure about is on screen rather than implied. The
     * name and brand are editable (the name is usually on a face the photo does
     * not show); the macros are editable too, which the OFF path does not need
     * — its numbers came from a database, these came from a model looking at a
     * photograph; the column the model says it read is stated, because per-100 g
     * and per-serving are a factor of several apart and story 192 is what
     * getting that wrong costs; and unread rows are named and left blank rather
     * than shown as a confident 0.
     */
    showLabelDraft(result: LabelReadResult, problem?: string, target: LabelDraftTarget | null = null): void {
        this.labelDraftValue = result;
        this.labelTargetValue = target;
        this.productValue = null;
        this.libraryItemValue = null;
        this.releaseNewFoodImage();
        const shadow = this.shadowRoot!;

        // Story 353: a library row keeps its identity, so it is shown rather than
        // offered for editing. An OFF match becomes a new row, so its name and brand
        // pre-fill the fields — the name it was scanned under beats one read off a
        // nutrition table, which rarely prints it.
        const library = target?.kind === 'library' ? target.item : null;
        const matched = target?.kind === 'product' ? offProductToNewFoodItem(target.product) : null;
        shadow.getElementById('product-name')!.textContent = library?.display_name ?? '';
        shadow.getElementById('product-brand')!.textContent = library?.brand ?? '';
        (shadow.getElementById('draft-name') as HTMLInputElement).value = matched?.display_name || result.draft.display_name;
        (shadow.getElementById('draft-brand') as HTMLInputElement).value = matched?.brand ?? result.draft.brand ?? '';
        shadow.getElementById('draft-identity')!.hidden = Boolean(library);
        shadow.getElementById('draft-name-error')!.hidden = true;

        const unit = result.draft.base_unit === 'ml' ? '100 ml' : '100 g';
        const basis = shadow.getElementById('draft-basis')!;
        basis.textContent = result.basis === 'per_100g'
            ? `Read from the per-${unit} column of the label.`
            : `This label prints only a per-serving column, so the values are per ${result.draft.base_amount} ${result.draft.base_unit}${result.draft.serving_label ? ` (${result.draft.serving_label})` : ''}.`;
        basis.hidden = false;

        // Fail loud, not friendly: when the read produced nothing, the model's
        // own words are what tell you whether to retake the photo or give up
        // and type. They replace the per-field note, which would otherwise list
        // every macro as unread and say nothing about why.
        const unread = shadow.getElementById('draft-unread')!;
        if (problem) {
            unread.textContent = `Could not read this label — fill it in by hand. ${problem}`;
            unread.hidden = false;
            basis.hidden = true;
        } else if (result.unread.length > 0) {
            unread.textContent = `Could not be read: ${sortUnread(result.unread).map(describeUnreadField).join(', ')}. Left blank rather than zero — type them in if you can read them.`;
            unread.hidden = false;
        } else {
            unread.textContent = '';
            unread.hidden = true;
        }

        this.renderMatchNote(null);
        this.setPendingBind(null);
        this.showPhoto();
        this.renderArchiveState();

        // Editable, unlike every other thing this surface shows: reviewing a
        // transcription you cannot correct is just looking at it.
        const form = shadow.getElementById('serving-form') as FoodServingForm;
        form.setAttribute('editable', '');
        form.data = foodItemToFormData(result.draft);
        this.applyMealTypeSelection();
    }

    /** The draft belongs to the label that produced it; anything else shown replaces it. */
    private clearLabelDraft(): void {
        this.labelDraftValue = null;
        this.labelTargetValue = null;
        const shadow = this.shadowRoot;
        if (!shadow) return;
        shadow.getElementById('draft-identity')!.hidden = true;
        shadow.getElementById('draft-basis')!.hidden = true;
        shadow.getElementById('draft-unread')!.hidden = true;
        shadow.getElementById('draft-name-error')!.hidden = true;
        // The OFF and library views are read-only by design — leaving the
        // editable template mounted would silently make their macros writable.
        shadow.getElementById('serving-form')!.removeAttribute('editable');
    }

    showLibraryItem(item: FoodItemBarcodeMatch, initialAmount?: number): void {
        this.libraryItemValue = item;
        this.productValue = null;
        this.clearLabelDraft();
        this.releaseNewFoodImage();
        const shadow = this.shadowRoot!;
        shadow.getElementById('product-name')!.textContent = item.display_name;
        shadow.getElementById('product-brand')!.textContent = item.brand ?? '';
        // Story 369 (shared-19): found through an in-store item code only — retailers number their
        // items independently and do collide, so this is a guess to check.
        this.setMatchNote(item.matched_by === 'item_code'
            ? 'Matched by product code — another package with this code was saved as this food. Check it is the same product.'
            : null);
        this.showPhoto();
        this.renderArchiveState();

        (shadow.getElementById('serving-form') as FoodServingForm).data = foodItemToFormData(item, initialAmount);
        this.applyMealTypeSelection();
    }

    /**
     * The picture of the food on screen (library, OFF or label draft), and whether it takes one in
     * this mode. A library row in log mode is PATCHed, so an offline pick queues against its id; a
     * food Log Food will create has no id yet (story 355).
     */
    private photoTarget(): PhotoTarget {
        if (this.libraryItemValue) {
            // add-ingredient mode is read-only (story 128: thumb visible, no controls).
            return {
                localRef: this.libraryItemValue.id,
                path: this.libraryItemValue.image_path ?? null,
                alt: this.libraryItemValue.display_name,
                editable: this.modeValue === 'log',
            };
        }
        // An OFF product with a picture keeps it — 343's drain adopts it after
        // the save — and so does a library match that has one. Anything else
        // here is a row with nothing to show (story 355).
        const editable = this.takesNewFoodImage();
        const matched = this.labelLibraryMatch();
        if (this.productValue) {
            return { localRef: null, path: null, remote: this.productValue.image_url ?? null, alt: this.productValue.product_name, editable };
        }
        if (matched) return { localRef: null, path: matched.image_path ?? null, alt: matched.display_name, editable };
        return { localRef: null, path: null, alt: '', editable };
    }

    /** Another food: the photo controls start over on it. */
    private showPhoto(): void {
        (this.shadowRoot!.getElementById('photo') as PhotoControls).show(this.photoTarget());
        this.renderLogHold();
    }

    /**
     * Story 355: a tap mid-upload would either create the row without the
     * photo or wait on it behind a button that looks idle — and a second
     * tap there is story 343's duplicate entry. A library row's photo is
     * PATCHed on its own, so it holds nothing.
     */
    private renderLogHold(): void {
        const logBtn = this.shadowRoot?.getElementById('log-btn') as HTMLButtonElement | null;
        if (logBtn) logBtn.disabled = this.photoUploading && this.takesNewFoodImage();
    }

    /**
     * Story 355 — the food on screen is one Log Food will create (or, for 353's
     * library match, fill in), and nothing has a picture of it yet.
     */
    private takesNewFoodImage(): boolean {
        if (this.modeValue !== 'log') return false;
        if (this.labelDraftValue) return !this.labelLibraryMatch()?.image_path;
        return !!this.productValue && !this.productValue.image_url;
    }

    /** Story 353 — the existing row a label draft fills in, when it is one. */
    private labelLibraryMatch(): FoodItem | null {
        return this.labelTargetValue?.kind === 'library' ? this.labelTargetValue.item : null;
    }

    /** The photo belongs to the food it was taken for; anything else shown lets go of it. */
    private releaseNewFoodImage(): void {
        this.newFoodImagePath = null;
    }

    /** The held photo, on the payload that creates the row — or, for a library match, that PATCHes it. */
    private withNewFoodImage<T extends { image_path?: string }>(item: T): T {
        return this.newFoodImagePath ? { ...item, image_path: this.newFoodImagePath } : item;
    }

    /**
     * A photo picked or removed in `<photo-controls>`. A food Log Food will create holds it for the
     * payload — uploaded on pick rather than on Log Food, so a 5–12 MB original goes while the food
     * is reviewed instead of while the save waits (story 355). A library row is PATCHed at once.
     */
    private async takePhoto(imagePath: string | null): Promise<void> {
        if (this.takesNewFoodImage()) {
            this.newFoodImagePath = imagePath;
            return;
        }
        if (!this.libraryItemValue || this.modeValue !== 'log') throw new Error('No food on screen takes a photo');
        this.libraryItemValue = await HealthService.updateFoodItem(this.libraryItemValue.id, { image_path: imagePath });
    }

    private async handleLog(): Promise<void> {
        const form = this.shadowRoot!.getElementById('serving-form') as FoodServingForm;
        const values = form.getCurrentValues();
        if (!values) {
            this.log.warn('handleLog: no valid amount — nothing dispatched');
            return;
        }
        const { servingAmount, serving } = values;

        // Story 338: the reviewed draft, before the add-ingredient branch —
        // a label read only ever reaches this surface in 'log' mode.
        if (this.labelDraftValue && this.modeValue === 'log') {
            // Story 353: a library match is filled in where it stands. Its name is
            // not the read's to supply, so there is no name to check.
            const target = this.labelTargetValue;
            if (target?.kind === 'library') {
                const reviewed = applyReviewedServing(this.labelDraftValue.draft, { servingAmount, serving });
                this.log.debug('handleLog dispatch', {
                    kind: 'existing',
                    source: 'label_photo',
                    foodItemId: target.item.id,
                    basis: this.labelDraftValue.basis,
                    amount: servingAmount,
                    unread: this.labelDraftValue.unread.length,
                });
                // No macro overrides: the row carries the reviewed numbers by the time
                // the entry is logged, and the server snapshots it (story 368).
                await dispatchAndSettle(this, createLogFoodEvent({
                    kind: 'existing',
                    food_item_id: target.item.id,
                    meal_type: this.getSelectedMealType(),
                    amount: servingAmount,
                    consumed_time: this.getSelectedTime(),
                    food_item_update: this.withNewFoodImage(labelNutritionUpdate(reviewed)),
                }));
                return;
            }

            const nameInput = this.shadowRoot!.getElementById('draft-name') as HTMLInputElement;
            const name = nameInput.value.trim();
            if (!name) {
                // A nameless row is not saveable (display_name is NOT NULL) and
                // an invented placeholder is a name someone keeps by accident.
                // So: say so, keep the form open, and put the cursor in it.
                this.shadowRoot!.getElementById('draft-name-error')!.hidden = false;
                nameInput.focus();
                this.log.warn('handleLog label draft: no name given — nothing dispatched');
                return;
            }
            // Also cleared here, not only on `input`: a name set from code (or
            // autofilled) never fires one, and a stale complaint next to a row
            // that just saved is worse than no complaint at all.
            this.shadowRoot!.getElementById('draft-name-error')!.hidden = true;
            const brand = (this.shadowRoot!.getElementById('draft-brand') as HTMLInputElement).value.trim();
            // Story 353: an OFF match lends the row its barcode, so the next scan of
            // it resolves locally — with nutrition this time.
            const reviewed = applyReviewedServing(
                {
                    ...this.labelDraftValue.draft,
                    barcode: target?.product.barcode,
                    canonical_name: name.toLowerCase(),
                    display_name: name,
                    brand: brand || undefined,
                },
                { servingAmount, serving },
            );
            this.log.debug('handleLog dispatch', {
                kind: 'new',
                source: 'label_photo',
                barcode: reviewed.barcode,
                basis: this.labelDraftValue.basis,
                base_amount: reviewed.base_amount,
                amount: servingAmount,
                unread: this.labelDraftValue.unread.length,
                image: !!this.newFoodImagePath,
            });
            await dispatchAndSettle(this, createLogFoodEvent({
                kind: 'new',
                new_food_item: this.withNewFoodImage(reviewed),
                meal_type: this.getSelectedMealType(),
                amount: servingAmount,
                consumed_time: this.getSelectedTime(),
            }));
            return;
        }

        if (this.modeValue === 'add-ingredient') {
            // For ingredients, the food item must exist (the meal save flow needs an id).
            const source = this.libraryItemValue ? 'library'
                : this.productValue ? 'off'
                : 'none';
            this.log.debug('handleLog add-ingredient', { source, amount: servingAmount });
            const foodItem = this.libraryItemValue
                ?? (this.productValue ? await this.offProductRow(this.productValue) : null);
            if (!foodItem) {
                this.log.warn('handleLog add-ingredient: no food item resolved — nothing dispatched');
                return;
            }
            this.dispatchEvent(createAddIngredientEvent({ food_item: foodItem, amount: servingAmount }));
            return;
        }

        if (this.libraryItemValue) {
            // Story 368 (pwa-nutrition-02): no macro overrides. The form here is
            // read-only, so it could only repeat the row — with every unknown
            // filled in as 0, and an override beats the server's own snapshot.
            this.log.debug('handleLog dispatch', { kind: 'existing', foodItemId: this.libraryItemValue.id, amount: servingAmount });
            await dispatchAndSettle(this, createLogFoodEvent({
                kind: 'existing',
                food_item_id: this.libraryItemValue.id,
                meal_type: this.getSelectedMealType(),
                amount: servingAmount,
                consumed_time: this.getSelectedTime(),
            }));
            return;
        }

        if (this.productValue) {
            // OFF product: send the new-food payload so the parent can call the
            // atomic create+log endpoint. No food row is created if the log fails.
            this.log.debug('handleLog dispatch', { kind: 'new', barcode: this.productValue.barcode, amount: servingAmount, image: !!this.newFoodImagePath });
            await dispatchAndSettle(this, createLogFoodEvent({
                kind: 'new',
                new_food_item: this.withNewFoodImage(offProductToNewFoodItem(this.productValue)),
                meal_type: this.getSelectedMealType(),
                amount: servingAmount,
                consumed_time: this.getSelectedTime(),
            }));
            return;
        }

        this.log.warn('handleLog: no library item or OFF product set — nothing dispatched');
    }

    private applyMealTypeSelection(): void {
        const mealSelect = this.shadowRoot?.getElementById('meal-type') as HTMLSelectElement | null;
        if (mealSelect) {
            mealSelect.value = this.defaultMealTypeValue ?? getDefaultMealType();
        }
        // Eaten-at default: "now" in the app zone, editable (story 260). Reset
        // alongside the meal-type default whenever a new item is shown.
        const timeInput = this.shadowRoot?.getElementById('consumed-time') as HTMLInputElement | null;
        if (timeInput) {
            timeInput.value = nowHHMM(getAppTimeZone());
        }
    }

    private getSelectedMealType(): MealType {
        return ((this.shadowRoot?.getElementById('meal-type') as HTMLSelectElement | null)?.value as MealType) ?? getDefaultMealType();
    }

    /** The editable eaten-at `HH:MM`; null when the user cleared the field (log unstamped). */
    private getSelectedTime(): string | null {
        const value = (this.shadowRoot?.getElementById('consumed-time') as HTMLInputElement | null)?.value;
        return value ? value : null;
    }
}

if (!customElements.get('food-log-detail')) {
    customElements.define('food-log-detail', FoodLogDetail);
}
